import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        N = int(next(iterator))
    except StopIteration:
        return

    events = []
    for _ in range(N):
        s = int(next(iterator))
        t = int(next(iterator))
        events.append((s, t))

    days = [False] * 366  # Days 1 to 365

    for s, t in events:
        for day in range(s, t + 1):
            days[day] = True

    count = 0
    for day in range(1, 366):
        if days[day]:
            count += 1

    print(count)

if __name__ == "__main__":
    solve()

